# Stories for albums 51–100: original Hebrew (not the book's text), three short paragraphs
# (who & when / what you hear / why it matters) and three picks whose names match the track names.
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(51, [
 "אוטיס רדינג, זמר צעיר מג'ורג'יה, הקליט את האלבום הזה בסוף 1965 באולפני סטקס שבמפיס. כמעט כולו נוצר, לפי הסיפור, ביום אחד, עם להקת הבית של סטקס, בוקר טי והאם.ג'י'ס, וקטע חצוצרות חזק.",
 "רדינג שר סול שנשמע כמו שיחה עם הלב: שלושה שירים של סם קוק, שנפטר כמה חודשים קודם, שירים משלו, וגרסאות מפתיעות ל־Satisfaction של הרולינג סטונס ול־My Girl של הטמפטיישנס, עם הרבה יותר בטן ופחות ניקיון.",
 "Otis Blue נחשב לאחד מאלבומי הסול הגדולים. כאן נולד Respect, שיר שאריתה פרנקלין תהפוך ב־1967 להמנון. שווה להשוות עם אלבום 38, ההופעה החיה של סם קוק."],
 [("Respect","השיר המקורי, שלימים אריתה פרנקלין הפכה להמנון. כאן הוא קצבי, גברי ומלא חצוצרות."),("A Change Is Gonna Come","הגרסה של רדינג לשיר של סם קוק, איטית ורוויית כאב."),("I've Been Loving You Too Long (To Stop Now)","אחת הבלדות הגדולות של הסול, ומפגן של שליטה בקול.")])

add(52, [
 "בסוף 1964 הפסיק בריאן ווילסון להופיע עם הביץ' בויז וסגר את עצמו באולפן, כדי לכתוב ולהפיק. The Beach Boys Today! הוא האלבום הראשון שמראה את הכיוון החדש: פחות גלים ומכוניות, יותר שירי אהבה וגעגוע.",
 "הצד הראשון מלא קצב והרמוניות מושלמות, כולל Help Me, Rhonda שהגיע לראש המצעד האמריקאי. הצד השני שקט ואישי בהרבה, עם בלדות כמו Please Let Me Wonder ו־She Knows Me Too Well, ובסוף יש גם קטע של שיחת אולפן מוקלטת.",
 "זה המקום שבו אפשר לשמוע את המעבר מלהקת פופ נעימה לקראת מה שיבוא בקרוב: אלבום 61, Pet Sounds. אם אהבתם את הסיפור הזה, המשיכו לשם."],
 [("Help Me, Rhonda","הלהיט הגדול של האלבום, עם הרמוניות קוליות ששווה להקשיב להן בקשב."),("Please Let Me Wonder","בלדה רכה ומדויקת שמקדימה את Pet Sounds."),("When I Grow Up (To Be a Man)","שיר על חרדה מלהתבגר, כתוב בכנות מפתיעה.")])

add(54, [
 "B.B. King, בן למשפחת עובדי שדה במיסיסיפי, הפך לאחד מגיטריסטי הבלוז החשובים בעולם. ב־21 בנובמבר 1964 הוא הופיע בתיאטרון ריגל שבשיקגו, מול קהל צעיר שמכיר כל מילה, והקליטו את המופע.",
 "מהרגע הראשון הקהל צועק, מוחא כפיים ומגיב לכל תו של הגיטרה שלו, שנקראת Lucille. התקליט קצר וחם, עם Everyday I Have the Blues, How Blue Can You Get? ו־Sweet Little Angel, והגיטרה שרה כמעט כמו הקול.",
 "Live at the Regal נחשב לאחד מתקליטי ההופעה החיה הגדולים ביותר. הוא השפיע על דור שלם של גיטריסטים, שהאזינו לו וניסו לחקות את הצליל שלו."],
 [("Everyday I Have the Blues","הפתיחה החמה, ובה הלהקה נכנסת ובי.בי. מתחיל לשיר."),("How Blue Can You Get?","שיר על עלבון ועל אהבה, עם ההומור היבש של קינג."),("Sweet Little Angel","סולו גיטרה שמתכתב עם הקול, והקהל מתלהב.")])

add(55, [
 "בסוף 1965 היו הביטלס בשיא הפופולריות, אבל כבר רצו משהו אחר. Rubber Soul הוקלט בתוך כארבעה שבועות, כדי להספיק לחג המולד, והוא נשמע כבר כמו להקה שרוצה לספר משהו אישי יותר.",
 "בין השירים נשמעים גיטרה אקוסטית ביתית, סיטאר של ג'ורג' הריסון ב־Norwegian Wood, ומילים עמוקות יותר, כמו ב־In My Life וב־Nowhere Man. בגרסה הבריטית, שאותה תשמעו כאן, יש ארבעה עשר שירים.",
 "האלבום סימן את המעבר של הביטלס מלהקת להיטים ליוצרים שמתייחסים לאלבום כאל יצירה שלמה. הוא הוביל ישירות אל אלבום 60, Revolver, ואל Pet Sounds של הביץ' בויז (אלבום 61), שנוצר כתגובה לו."],
 [("Norwegian Wood (This Bird Has Flown)","הופעה ראשונה של סיטאר בשיר רוק גדול."),("In My Life","נוסטלגיה בלי סנטימנטליות, אחד מהשירים האהובים של הלהקה."),("Nowhere Man","שיר על אדם בלי כיוון, שג'ון לנון כתב אחרי לילה של תקיעות.")])

add(56, [
 "ברט ג'אנש, גיטריסט צעיר מסקוטלנד, הקליט את אלבום הבכורה שלו ב־1965 בדירה של המהנדס ביל לידר, על מכשיר הקלטה ביתי. התקליט נמכר לחברת התקליטים תמורת סכום קטן, והפך אחרי זמן לקלאסיקה.",
 "רק גיטרה אקוסטית וקול שקט, בנגינה מהירה ומורכבת שנשמעת קלילה. בין השירים יש Needle of Death, שיר על מותו של חבר, וקטעים אינסטרומנטליים כמו Angie ו־Casbah.",
 "הנגינה של ג'אנש השפיעה על גיטריסטים רבים בבריטניה ומחוצה לה. זה אחד התקליטים שאפשר לשים ברקע, ולגלות אחרי כמה שירים שכבר הפסקתם לעשות דבר אחר."],
 [("Needle of Death","שיר עצוב וקצר, שנשמע כמעט כמו תפילה."),("Angie","קטע גיטרה אינסטרומנטלי מפורסם, מהיר ועדין."),("Strolling Down the Highway","פתיחה נעימה שמכניסה לעולם של האלבום.")])

add(57, [
 "The Byrds התחילו ב־1964 בלוס אנג'לס, והגדירו את הצליל של ה־folk rock. במרץ 1965 הקליטו את Mr. Tambourine Man, גרסה חשמלית לשיר של בוב דילן, ועלו לראש המצעדים בארצות הברית ובבריטניה.",
 "רוג'ר מקגווין מנגן על גיטרה בת שתים עשרה מיתרים, והצליל הצלצלני שלה פותח את השיר, ומעליו הרמוניות של חברי הלהקה. האלבום מכיל עוד גרסאות לשירי דילן ושירים משלהם, ובהם The Bells of Rhymney, שיר על פי שיר של משורר וולשי.",
 "האלבום הראה שאפשר לחבר בין מילים של פולק לבין קצב של רוק, והשפיע על מוזיקאים רבים. את המקור של דילן תמצאו באלבום 50, Bringing It All Back Home."],
 [("Mr. Tambourine Man","הגרסה שהפכה את דילן ללהיט פופ. נגינה בהירה והרמוניות."),("The Bells of Rhymney","שיר פולק וולשי, משתלב בגיטרות חשמליות."),("Chimes of Freedom","עוד שיר של דילן, עם צלצולי גיטרה שאינם נגמרים.")])

add(58, [
 "ביולי 1965 עלה בוב דילן לבמה בפסטיבל הפולק של ניופורט עם להקה חשמלית, והקהל התחלק בין מריעים למוחים. חודש אחר כך יצא Highway 61 Revisited, ובו לקח את הרוק אל עולם המילים שלו.",
 "האלבום נפתח ב־Like a Rolling Stone, שיר ארוך על נפילה מהגובה, עם אורגן שאל קופר ניגן בו כמעט בלי תכנון. הוא מסתיים ב־Desolation Row, שיר אקוסטי של כאחת עשרה דקות שמצייר תמונה של דמויות מוזרות.",
 "זה אחד האלבומים החשובים בתולדות הרוק, ולצידו ממשיכים Bringing It All Back Home (אלבום 50) ו־Blonde on Blonde (אלבום 64), השלישייה שבה דילן שינה את הכללים."],
 [("Like a Rolling Stone","הבסיס של הכול, ואחד השירים הגדולים ביותר בהיסטוריה של הרוק."),("Ballad of a Thin Man","שיר מרושע ואפל, על אדם שלא מבין את מה שקורה סביבו."),("Desolation Row","שיר אקוסטי ארוך ומלא דמויות, שקט אחרי הסערה.")])

add(59, [
 "The Who היו ארבעה בחורים מלונדון, ובסוף 1965 הוציאו את האלבום הראשון שלהם. פיט טאונשנד כתב את רוב השירים, והלהקה נשמעה כמו משהו שעומד להתפוצץ ברגע הבא.",
 "האלבום כולל את My Generation, שיר עם גמגום והשורה המפורסמת על כך שעדיף למות לפני שמזדקנים. יש בו גם גרסאות לשירי ג'יימס בראון, ובאמצע קטע אינסטרומנטלי אנרגטי בשם The Ox.",
 "זה קול של דור שלם שמדבר חזק. רואים כאן את ההתחלה של להקה שתיצור אחר כך את Tommy ואת Who's Next, ושל סגנון הרוק הקשה והישיר."],
 [("My Generation","הריף והגמגום המפורסם, ההמנון של ההתמרדות."),("The Kids Are Alright","שיר פופ מתוק וישר, עם הרמוניות נקיות."),("The Ox","קטע אינסטרומנטלי אנרגטי, שבו נשמעים כל הכלים.")])

add(60, [
 "אחרי שנים של סיבובי הופעות, הביטלס החליטו ב־1966 שהם רוצים לעשות מוזיקה שאי אפשר להשמיע על במה. Revolver הוקלט באולפני אבי רוד, עם מהנדסים שעזרו להם לנסות צלילים חדשים.",
 "האלבום נפתח ב־Taxman של ג'ורג' הריסון, כולל מיתרים בלבד ב־Eleanor Rigby, שירה חבורתית ב־Yellow Submarine, ובסוף Tomorrow Never Knows, קטע ניסיוני עם לולאות סרט. כל שיר נשמע כמו עולם משלו.",
 "רבים רואים בו את האלבום הטוב ביותר של הביטלס. הוא ההמשך של Rubber Soul (אלבום 55) והכנה ל־Sgt. Pepper (אלבום 78)."],
 [("Eleanor Rigby","שיר על בדידות, מלווה במיתרים בלבד."),("Tomorrow Never Knows","סיום ניסיוני שנשמע כמו משהו מעולם אחר."),("Here, There and Everywhere","בלדה עדינה שפול מקרטני כתב, אחת האהובות של הלהקה.")])

add(61, [
 "בריאן ווילסון שמע את Rubber Soul של הביטלס, והחליט שהוא רוצה ליצור משהו גדול יותר. במשך חודשים הוא עבד באולפן עם נגנים מקצועיים ועם המילים של טוני אשר, והתוצאה יצאה במאי 1966.",
 "האלבום מלא עיבודים מפתיעים: חליל, פעמונים, ואפילו קולות של כלבים ורכבת. השירים, כמו Wouldn't It Be Nice, God Only Knows ו־Caroline, No, מדברים על געגוע, על הפחד מהתבגרות ועל אהבה שאולי לא תחזיק.",
 "Pet Sounds הוא אחד האלבומים המשפיעים ביותר. הוא דחף את הביטלס לכתוב את Sgt. Pepper (אלבום 78), ופול מקרטני אמר אחר כך ש־God Only Knows הוא השיר האהוב עליו."],
 [("God Only Knows","שיר אהבה יוצא דופן, שנפתח דווקא בפחד מהעתיד."),("Wouldn't It Be Nice","פתיחה נוצצת, על נערים שרוצים כבר להתחתן."),("Caroline, No","סיום עצוב על אהבה שהשתנתה.")])

add(62, [
 "פרד ניל היה זמר ומלחין מגריניץ' וילג' שבניו יורק, עם קול עמוק וחם ותדמית של אדם שאוהב להתרחק מהאור. האלבום הזה, שהוקלט בשנות ה־60 המאוחרות, נשאר מוכר בעיקר בזכות שיר אחד.",
 "הגיטרה האקוסטית מנגנת בקצב מתגלגל, וקולו של ניל מתנהג כמו מישהו שלא ממהר לשום מקום. Everybody's Talkin' נכתב על ידו, ולימים הפך ללהיט בגרסה של הארי נילסון. בסוף האלבום יש Cynicrustpetefredjohn Raga, קטע ארוך של אלתור.",
 "זה תקליט של פולק בלי מהומה: הוא נשמע כאילו הוקלט בסלון. אם אהבתם את הפולק החשמלי של דילן והבירדס, שווה להקשיב גם לצד השקט ביותר של התקופה."],
 [("Everybody's Talkin'","השיר המפורסם ביותר של ניל, שנשמע כאן פשוט ואינטימי."),("The Dolphins","שיר על אהבה ועל חופש, ואחד האהובים על מוזיקאים אחרים."),("That's The Bag I'm In","בלוז פולק מהיר, עם הגיטרה בחזית.")])

add(63, [
 "בסוף 1965 התחילו הבירדס להתרחק מהפולק, ובאלבום השלישי שלהם, Fifth Dimension, כבר נשמעים צלילים שלא קיימים במסורת. בלי גן קלארק, שעזב, נשארה הלהקה עם רוג'ר מקגווין וגיטרות מוזרות.",
 "ב־Eight Miles High שומעים בגיטרה של מקגווין השפעה של הסקסופון של ג'ון קולטריין ושל הסיטאר של ראווי שנקר. גם 5D, שיר על המימד החמישי, הוא ניסוי. יש כאן גם שירים פשוטים וחמים, כמו Wild Mountain Thyme.",
 "האלבום נחשב לאחד הצעדים הראשונים של הרוק אל הפסיכדליה. בהשוואה ל־Mr. Tambourine Man (אלבום 57) רואים כמה מהר התרחקה הלהקה מהסגנון שהמציאה."],
 [("Eight Miles High","סינגל שהראה לרוק דרך חדשה להשתמש בגיטרה."),("5D (Fifth Dimension)","שיר על המימד החמישי, שנשמע כמו כניסה לעולם אחר."),("Wild Mountain Thyme","שיר פולק סקוטי ישן, בעיבוד קליל.")])

add(64, [
 "אחרי Highway 61 Revisited (אלבום 58), נסע בוב דילן לנאשוויל וסיים ב־1966 את Blonde on Blonde, אחד הראשונים ברוק שיצאו כאלבום כפול. הוא הקליט עם נגני אולפן מקומיים שהתפעלו מהאופן שבו הוא כותב תוך כדי הקלטה.",
 "השירים כאן קצרים וארוכים, עוקצניים ורכים: Rainy Day Women #12 & 35 שנשמע כמו חגיגה, Visions of Johanna שנע בין חלום למציאות, Just Like a Woman, ובצד הרביעי שיר ענק, Sad-Eyed Lady of the Lowlands, שתופס לבדו כמעט את כל הצד.",
 "זה השיא של תקופת דילן הצעיר והחשמלי. אם אהבתם את Bringing It All Back Home (אלבום 50) ואת אלבום 58, זה המקום שבו הסיפור נסגר בענקיות."],
 [("Visions of Johanna","שיר שנע בין חלום למציאות, אחד הגדולים של דילן."),("Just Like a Woman","שיר אהבה שבור ועדין, ואחד הלהיטים של האלבום."),("Sad-Eyed Lady of the Lowlands","שיר ארוך מהדהד, שסוגר את האלבום.")])

add(65, [
 "The Monks היו חמישה חיילים אמריקאים שהתמקמו בגרמניה בשנות ה־60 והקימו יחד להקה. הם גילחו שערות על ראשם כמו נזירים, לבשו גלימות שחורות, עם חבל על הצוואר, והופיעו במועדונים בגרמניה.",
 "האלבום שלהם, שהוקלט ב־1966, מלא בקצב חזק ואגרסיבי, בנגינה בבנג'ו חשמלי, ובמילים שמרדניות ולא מנומסות. Monk Time הוא כמעט קריאה למרד, ו־I Hate You הוא בדיוק מה שהכותרת מבטיחה.",
 "בזמנו כמעט אף אחד לא שמע אותו, אבל עשרות שנים אחר כך גילו אותו מוזיקאים והבינו שהוא הקדים את הפאנק. זה אחד האלבומים הכי מוזרים ברשימה, ובמובן טוב."],
 [("Monk Time","הפתיחה, כמעט הצהרת כוונות של הלהקה."),("I Hate You","שיר קצר ועוקצני, עם קצב מהיר."),("Complication","אחד הסינגלים של הלהקה, קצבי ומוזר.")])

add(66, [
 "ריי דייויס, הכותב של הקינקס, החליט ב־1966 שהוא רוצה לכתוב על אנשים ולא רק על אהבה. Face to Face הוא האלבום הראשון שבו הוא נשמע כמו מספר סיפורים, עם הומור בריטי חד.",
 "השירים מציירים דמויות: Dandy הפלרטטן, Session Man המוזיקאי שכולם משתמשים בו, ו־Sunny Afternoon, על אדם שאיבד את כל כספו לרשויות המס ויושב לו בשמש. בין השירים נשמעים אפקטים, כמו גלים וצלצולים, שמחברים את הכול.",
 "האלבום מסמן את המעבר של הקינקס מלהקת ריף חדה ללהקה שמתבוננת בחיים. הוא מוביל אל Something Else (אלבום 97) ואל The Kinks Are the Village Green Preservation Society."],
 [("Sunny Afternoon","להיט קליל עם מילים עצובות על אדם שהפסיד הכול."),("Dandy","דיוקן קליל ואירוני של רווק שלא רוצה להתחייב."),("Session Man","שיר על נגן אולפן שנשמע כמו ליווי מבוים.")])

add(67, [
 "The Mamas & The Papas היו ארבעה מוזיקאים מקליפורניה: ג'ון ומישל פיליפס, קאס אליוט ודני דוהרטי. ב־1966 יצא האלבום הראשון שלהם, ובו שני שירים שהפכו ללהיטי ענק.",
 "הקולות של הארבעה מתחברים להרמוניות עשירות, ומעליהם קולה החם והעמוק של קאס אליוט. California Dreamin' הוא שיר על חורף בניו יורק וגעגוע לשמש, ו־Monday, Monday עלה לראש המצעד האמריקאי. יש גם גרסאות נוספות, כמו Spanish Harlem.",
 "זה צליל הפופ של קליפורניה של אמצע שנות ה־60, בין חלום לזיכרון. שווה להשוות עם הביץ' בויז (אלבום 52) ועם הבירדס (אלבום 57)."],
 [("California Dreamin'","געגוע לשמש ביום חורפי, עם סולו חליל מפורסם."),("Monday, Monday","שיר שמח שנפתח בעצב על יום שני."),("Go Where You Wanna Go","שיר על עזיבה, בעיבוד קולי מורכב.")])

add(68, [
 "Paul Revere & the Raiders היו להקה מהצפון־מערב של ארצות הברית שהופיעה בתחפושות של מהפכנים אמריקאים מהמאה ה־18. הם נחשבו לכוכבי טלוויזיה בזכות תוכנית פופולרית לנוער.",
 "האלבום Midnight Ride מ־1966 מלא בקצב גיטרות חד, ובקולו של מארק לינדזי. Kicks הוא שיר נגד סמים שהפך ללהיט, ו־Louie, Go Home מזכיר את המקצבים של הגראז' רוק.",
 "אחרי כמה עשורים חזרו לזהות בלהקה הזאת משהו חשוב: את הגראז' רוק האמריקאי של אמצע שנות ה־60, מלא אנרגיה ופחות נוצץ מהלהיטים הגדולים של הביטלס."],
 [("Kicks","שיר נגד סמים שנשמע כמו חגיגה."),("I'm Not Your Stepping Stone","שיר קצבי וחצוף, שלהקות פאנק ביצעו לימים בעצמן."),("Get It On","רוק פשוט וישיר, עם הרבה קצב.")])

add(69, [
 "פרנק זאפה ולהקתו, The Mothers of Invention, הוציאו ב־1966 אחד האלבומים הכפולים הראשונים בתולדות הרוק. הם התכוונו להרים גבה ולצחוק על הפופ, אבל גם לומר משהו רציני.",
 "האלבום מכיל חמישה עשר שירים ומלא בהומור מוזר, בלחנים מעוותים ובקולות שונים. Hungry Freaks, Daddy פותח בהתקפה על החברה האמריקאית, ו־Trouble Every Day נכתב על מהומות בלוס אנג'לס. הצד האחרון שוקע בקטע ארוך של אלתור ורעש.",
 "זה אלבום שהראה שאפשר להשתמש ברוק לא רק לשירי אהבה. זאפה המשיך בדרך הזאת עשרות שנים, וזה מקום טוב להתחיל בו."],
 [("Hungry Freaks, Daddy","פתיחה שנוגעת במה שזאפה חושב על אמריקה."),("Trouble Every Day","שיר על מהומות בעיר, בלוז חד וכועס."),("Who Are the Brain Police?","שיר אפל וחלומי על שליטה בחברה.")])

add(70, [
 "Aftermath מ־1966 הוא האלבום הראשון של הרולינג סטונס שכל שיריו נכתבו על ידי מיק ג'אגר וקית' ריצ'רדס. לפני זה הם הקליטו בעיקר גרסאות לשירי בלוז ורוק'נרול.",
 "בריאן ג'ונס, הגיטריסט, ניסה כאן כלים חדשים: סיטאר ב־Paint It, Black, מרימבה ב־Under My Thumb ודולצימר ב־Lady Jane. בגרסה האמריקאית, שאותה תשמעו כאן, יש אחד עשר שירים, ובהם גם Stupid Girl ו־Think.",
 "זה אלבום שמראה שהסטונס יכולים ליצור לבד, בלי לחקות. אם אהבתם את England's Newest Hit Makers (אלבום 46), כאן תראו איך הם גדלו."],
 [("Paint It, Black","סיטאר וקצב שנשמעים כמו מרדף, אחד הלהיטים הגדולים שלהם."),("Under My Thumb","קצב מתפתל עם מרימבה, ושיר שנוי במחלוקת."),("Lady Jane","בלדה עדינה עם דולצימר.")])

add(71, [
 "סיימון וגרפונקל, שניים מניו יורק, הפכו ב־1966 לצמד פולק פופולרי במיוחד. האלבום מלא בשירים שמגיבים למה שקורה סביבם.",
 "האלבום נפתח ב־Scarborough Fair / Canticle, שילוב של בלדה אנגלית עתיקה ושיר מחאה נגד מלחמה. Homeward Bound מדבר על געגוע הביתה, ו־The 59th Street Bridge Song (Feelin' Groovy) קליל וחייכני. בסוף מופיע 7 O'Clock News / Silent Night, שמערבב שידור חדשות מציאותי עם שיר חג המולד.",
 "זה תקליט של מילים חכמות ולחנים מדויקים, ואחד המקומות הטובים להכיר את סיימון וגרפונקל בשיאם המוקדם."],
 [("Scarborough Fair / Canticle","בלדה עתיקה שהפכה למשהו חדש לגמרי."),("Homeward Bound","געגוע לבית שמלווה כל נוסע."),("7 O'Clock News / Silent Night","שיר חג ששומעים בו חדשות, ניסוי מוזר וחכם.")])

add(72, [
 "13th Floor Elevators היו להקה מאוסטין שבטקסס, בהובלת הזמר רוקי אריקסון. ב־1966 הם הקליטו את אחד האלבומים הראשונים שהציגו את עצמם כפסיכדליים, עוד לפני שהמילה נהייתה מוד.",
 "הצליל שלהם מיוחד: גיטרות חשמליות חדות, קול נסער של אריקסון, ומעל הכול צליל מוזר מקנקן קרמיקה שמחובר למיקרופון, שטומי הול היה מנגן ומפיק ממנו בועות. You're Gonna Miss Me הוא שיר גראז' מפורסם, ו־Roller Coaster מתגלגל ומסחרר.",
 "זה תקליט שהוקלט בפשטות אבל נשמע כמו משהו מעולם אחר. הוא השפיע על להקות גראז' ופסיכדליה בשנים שאחר כך."],
 [("You're Gonna Miss Me","שיר גראז' פרוע עם צעקות של אריקסון, אחד המפורסמים של התקופה."),("Roller Coaster","שיר מתגלגל עם צליל בועות מוזר."),("Reverberation (Doubt)","שיר על ספק, עם גיטרה שמהדהדת.")])

add(73, [
 "אריק קלפטון עזב ב־1965 את הירדבירדס והצטרף ללהקה של ג'ון מאייל, מוזיקאי בלוז בריטי שאסף סביבו נגנים צעירים. ב־1966 הקליטו יחד את האלבום הזה, שנקרא לפעמים Beano Album, כי קלפטון מחזיק בעטיפה את המגזין Beano.",
 "קלפטון מנגן על גיטרת גיבסון דרך מגבר חזק, והצליל שלו הפך לסמל של הבלוז הבריטי. בין השירים שירי בלוז אמריקאיים כמו Hideaway ו־All Your Love, ואחד מהם, What'd I Say, מציג את הלהקה בצד ההופעה.",
 "זה אחד האלבומים שהתחילו את העידן של גיטריסט־גיבור. חודשים ספורים אחר כך עזב קלפטון והקים את Cream, שאלבומה Disraeli Gears הוא אלבום 88."],
 [("All Your Love","גיטרה בוכייה פותחת את האלבום."),("Hideaway","קטע אינסטרומנטלי שהפך לסימן היכר של קלפטון."),("Ramblin' on My Mind","בלוז ישן שנוגן כאן בעדינות.")])

add(74, [
 "בשנת 1966 הקליטו הירדבירדס אלבום שהתחיל לעמוד ברגליו. הגיטריסט ג'ף בק, שהחליף את קלפטון, כבר היה הכוכב של הלהקה, והלהקה נכנסה לאולפן עם רעיונות מפתיעים.",
 "האלבום מכיל שירים כמו Over Under Sideways Down, ש־Lost Woman ו־The Nazz Are Blue ממשיכים אותו בחשמל ובמוזרות. גיטרת בק מרחפת, מצחקקת, ומפזרת צלילים שנשמעים כמעט כמו סינתיסייזר. יש גם קטעים קצרים ורוקנרול ישר.",
 "הירדבירדס הפכו כאן ללהקה שמביאה גיטריסטים גדולים אחד אחרי השני. שתי סיבות טובות לשמוע: בק בשיאו, וההשפעה על להקות הרוק הקשה בשנים הבאות."],
 [("Over Under Sideways Down","סינגל קצבי עם גיטרה מזרחית מוזרה."),("Lost Woman","בלוז מהיר שנפתח כמו מרוץ."),("The Nazz Are Blue","בלוז שבו ג'ף בק גם שר וגם מנגן.")])

add(75, [
 "נינה סימון הייתה פסנתרנית שלמדה קלאסי, והפכה לזמרת ג'אז, בלוז ופולק עם קול עמוק וייחודי. ב־1966 יצא האלבום Wild Is the Wind, שכולל הקלטות מכמה שנים.",
 "בין השירים Four Women, פורטרט של ארבע נשים שחורות עם ארבע גורלות שונים; Lilac Wine, ליריקה בעדינות; והשיר הכותרת, Wild Is the Wind, שדיוויד בואי יגיש ממנו גרסה משלו כעשור אחר כך.",
 "זה אלבום שמראה את היכולת של סימון לעבור בין כאב, כעס ורוך בתוך אותו שיר. אם אהבתם את הקול של בילי הולידיי (אלבום 16), תכירו עוד אחת שלא ממלאת תפקיד."],
 [("Four Women","ארבע דמויות בארבעה פסקי זמן, ושיר אמיץ מהתקופה."),("Lilac Wine","שיר שקט ורך, עם קול שנשמע כמעט כמו לחישה."),("Wild Is the Wind","שיר אהבה מסוכן ותאב, אחד הגדולים של סימון.")])

add(76, [
 "אסטרוד ג'ילברטו נעשתה מפורסמת בזכות הקול הקל והמרוחק שלה בשיר The Girl from Ipanema באלבום Getz / Gilberto (אלבום 41). Beach Samba יצא ב־1967 ומציג אותה בשמש, בסגנון סמבה נינוח.",
 "האלבום מעורב: שירים ברזילאיים כמו Canoeiro ו־Nao Bate O Coracao, לצד סטנדרטים אמריקאיים כמו I Had the Craziest Dream ו־My Foolish Heart. הקול שלה תמיד מתבונן מרחוק, כאילו היא שרה לעצמה.",
 "זה תקליט קצר ומרגיע, מתאים ליום חופשי. הוא עוזר להבין למה הבוסה נובה כבשה את העולם באותה תקופה."],
 [("Stay","פתיחה רכה, עם קול צלול ומרוחק."),("Beach Samba (Bossa na praia)","שיר הכותרת, קצבי וקליל כמו יום בחוף."),("My Foolish Heart","בלדה אמריקאית מפורסמת בגרסה ברזילאית.")])

add(77, [
 "ניקו, זמרת גרמנייה שהופיעה עם הוולוט אנדרגראונד באלבום הראשון שלהם (אלבום 91), הקליטה ב־1967 אלבום סולו משלה, Chelsea Girl. השירים נכתבו בין היתר על ידי ג'קסון בראון, שהיה אז בן 17 בערך.",
 "קולה נמוך, קר ומוזר, והוא מתערבב עם גיטרות אקוסטיות ועם עיבודי כלי קשת שהמפיק הוסיף מעליו. אחד השירים מתחבר לבוב דילן, I'll Keep It With Mine, ואחר, These Days של ג'קסון בראון, הפך לקלאסיקה.",
 "ניקו עצמה לא אהבה את העיבודים המעודנים, אבל הקהל אהב. זה אחד התקליטים העדינים והמוזרים של התקופה."],
 [("These Days","שיר עצוב של ג'קסון בראון בקולה של ניקו."),("I'll Keep It With Mine","שיר של בוב דילן, כאן עדין ורחוק."),("Chelsea Girls","שיר על מלון בניו יורק ועל האנשים שגרו בו.")])

add(78, [
 "ב־1967 החליטו הביטלס להפסיק להופיע ולהתמסר לאולפן. Sgt. Pepper's Lonely Hearts Club Band הוקלט במשך חודשים, עם ג'ורג' מרטין כמפיק, והוצג כאילו זו להקה בדיונית אחרת בשם כתוב על העטיפה.",
 "האלבום מלא בצלילים חדשים: סיטאר ב־Within You Without You, תזמורת ב־A Day in the Life, ושירים מוזרים ומקסימים כמו Lucy in the Sky with Diamonds ו־Being for the Benefit of Mr. Kite!. המעבר בין השירים כמעט לא נשבר.",
 "זה נחשב לאחד האלבומים המשפיעים בהיסטוריה, וקבע שאלבום יכול להיות יצירה שלמה. הוא בא אחרי Revolver (אלבום 60), והוא מחווה גם ל־Pet Sounds (אלבום 61)."],
 [("A Day in the Life","סיום גדול עם תזמורת וצליל אחרון שמתמשך."),("Lucy in the Sky with Diamonds","שיר חלומי עם דימויים צבעוניים."),("With a Little Help from My Friends","רינגו שר שיר שמח ופשוט על חברות.")])

add(79, [
 "Country Joe and the Fish היו להקה מברקלי שבקליפורניה, שהתמקדה בפסיכדליה ובמחאה פוליטית. Electric Music for the Mind and Body יצא ב־1967, שנת ה־Summer of Love.",
 "האלבום מלא בגיטרות חשמליות, באורגן מהדהד ובמילים על סמים, על אהבה ועל חופש. Section 43 הוא קטע ארוך אינסטרומנטלי שמסתובב כמו ערפל, ו־Flying High פותח את האלבום בקצב חיוני.",
 "זה אחד האלבומים שמראים איך נשמעה ברקלי של אותה תקופה. אם אהבתם את הצליל של אלבום 96, Surrealistic Pillow, כאן תמצאו עוד ממנו."],
 [("Flying High","פתיחה קצבית ומלאת הבטחות."),("Section 43","קטע ארוך שמזכיר מסע."),("Grace","סיום שקט ומהורהר.")])

add(80, [
 "Buffalo Springfield היו להקה שבה נפגשו שלושה יוצרים גדולים: סטיבן סטילס, ניל יאנג וריצ'י פיורי. ב־1967 הם הקליטו את האלבום השני שלהם, והמתחים בין החברים כמעט הפריעו לו.",
 "כל אחד הוסיף שירים משלו, וכך יצא אלבום מגוון: Mr. Soul של יאנג נפתח בגיטרה חדה, Expecting to Fly מתנשא עם תזמורת, ו־Bluebird של סטילס מתחיל באקוסטית ומסתיים בסולו רועם.",
 "זה אחד האלבומים שבנו את הגשר בין הפולק, הרוק והקאנטרי. מחבריה יצאו כמה מהיוצרים הגדולים של שנות ה־70."],
 [("Mr. Soul","פתיחה חשמלית עם ריף חד וטקסט על תהילה."),("Expecting to Fly","שיר עדין עם תזמורת, כמעט חלום."),("Bluebird","שיר של סטילס עם סיום גיטרות חזק.")])

add(81, [
 "Moby Grape נוסדה בסן פרנסיסקו ב־1966, והייתה להקה של חמישה זמרים ויוצרים. Columbia הוציאה את האלבום הראשון שלהם ב־1967 בחגיגה גדולה, ואפילו שחררה כמה סינגלים בבת אחת, מה שהכביד עליהם.",
 "האלבום נשמע כמו כל מה שהיה אפשרי בסן פרנסיסקו: שלוש גיטרות שמתכתבות, הרמוניות, קאנטרי ובלוז, וחצי תריסר שירים שהיו יכולים להיות להיטים. Omaha, Hey Grandma ו־Sitting by the Window שווים האזנה.",
 "זה אלבום שהיה צריך להיות ענק ונשאר סוד יפה. אם אהבתם את Surrealistic Pillow (אלבום 96), זה חלק מאותו עולם."],
 [("Omaha","שיר קצבי עם שלוש גיטרות חשמליות."),("Hard Road to Follow","רוק חם ויציב."),("Better Day","שיר פשוט ואופטימי.")])

# ---- corrections to the drafts above (later add() calls replace earlier ones) ----
add(72, [
 "13th Floor Elevators היו להקה מאוסטין שבטקסס, בהובלת הזמר רוקי אריקסון. ב־1966 הם הוציאו אחד האלבומים הראשונים שהציגו את עצמם כפסיכדליים.",
 "הצליל שלהם מיוחד: גיטרות חשמליות חדות, קול נסער של אריקסון, ומעל הכול צליל בועות מוזר, שטומי הול הפיק בעזרת כד שהוא נפח בו מול מיקרופון. You're Gonna Miss Me הוא שיר גראז' פרוע, ו־Roller Coaster מסתחרר כמו שמו.",
 "זה תקליט גולמי שנשמע כמו משהו מעולם אחר, והשפיע על להקות גראז' ופסיכדליה בשנים שאחר כך."],
 [("You're Gonna Miss Me","שיר גראז' פרוע עם צעקות של אריקסון, אחד המפורסמים של התקופה."),("Roller Coaster","שיר מסתחרר עם צליל הבועות המוזר."),("Reverberation (Doubt)","שיר על ספק, עם גיטרה שמהדהדת.")])

add(73, [
 "אריק קלפטון עזב ב־1965 את הירדבירדס והצטרף ללהקה של ג'ון מאייל, מוזיקאי בלוז בריטי שאסף סביבו נגנים צעירים. ב־1966 הקליטו יחד את האלבום הזה, שנקרא לפעמים Beano Album, כי קלפטון מחזיק בעטיפה את המגזין Beano.",
 "קלפטון מנגן בגיטרת גיבסון דרך מגבר חזק, והצליל העבה שלו הפך לסמל של הבלוז הבריטי. האלבום מלא בשירי בלוז אמריקאיים, כמו All Your Love ו־Hideaway, בביצוע צעיר, חם ובוטה.",
 "זה אחד האלבומים שהתחילו את העידן של גיטריסט־גיבור. חודשים ספורים אחר כך עזב קלפטון והקים את Cream, שאלבומה Disraeli Gears הוא אלבום 88."],
 [("All Your Love","גיטרה בוכייה פותחת את האלבום."),("Hideaway","קטע אינסטרומנטלי שהפך לסימן היכר של קלפטון."),("Ramblin’ on My Mind","בלוז ישן, כאן בקולו הצעיר של קלפטון.")])

add(75, [
 "נינה סימון הייתה פסנתרנית קלאסית שהפכה לזמרת ג'אז, בלוז ופולק, עם קול עמוק וייחודי. ב־1966 יצא האלבום Wild Is the Wind, שבו היא שרה שירי אהבה וגם שיר על נשים שחורות שלא כל אחד היה מעז לשיר.",
 "בין השירים Four Women, דיוקן של ארבע נשים שחורות עם ארבעה גורלות שונים; Lilac Wine, בלדה רכה וחלומית; והשיר Wild Is the Wind, שדיוויד בואי יגיש ממנו גרסה משלו כעשור אחר כך.",
 "זה אלבום שמראה את היכולת של סימון לעבור בין כאב, כעס ורוך בתוך אותו שיר, ואת הכוח שיש בקול שאינו מנסה לרצות."],
 [("Four Women","ארבע דמויות בארבעה גורלות, ושיר אמיץ בזמנו."),("Lilac Wine","שיר שקט ורך, עם קול שנשמע כמעט כמו לחישה."),("Wild Is the Wind","שיר אהבה מסוכן ותאב, אחד הגדולים של סימון.")])

add(77, [
 "ניקו, זמרת גרמנייה שהופיעה עם הוולוט אנדרגראונד באלבום הראשון שלהם (אלבום 91), הקליטה ב־1967 אלבום סולו משלה, Chelsea Girl. אחדים מהשירים נכתבו על ידי ג'קסון בראון, שהיה אז נער.",
 "קולה נמוך, קר ומוזר, והוא מתערבב עם גיטרות אקוסטיות ועם עיבודים עדינים שהוסיפו מעליו. יש כאן שיר של בוב דילן, I'll Keep It With Mine, ו־These Days של ג'קסון בראון, שהפך לקלאסיקה.",
 "ניקו עצמה לא אהבה את העיבודים המעודנים, אבל האלבום נשאר אחד התקליטים העדינים והמוזרים של התקופה."],
 [("These Days","שיר עצוב של ג'קסון בראון בקולה של ניקו."),("I'll Keep It With Mine","שיר של בוב דילן, כאן עדין ורחוק."),("Chelsea Girls","שיר על מלון צ'לסי בניו יורק ועל האנשים שגרו בו.")])

add(78, [
 "ב־1967 החליטו הביטלס להפסיק להופיע ולהתמסר לאולפן. Sgt. Pepper's Lonely Hearts Club Band הוקלט במשך חודשים, עם ג'ורג' מרטין כמפיק, והוצג כאילו זו הופעה של להקה דמיונית בשם הזה.",
 "האלבום מלא בצלילים חדשים: סיטאר ב־Within You Without You, תזמורת ב־A Day in the Life, ושירים מוזרים ומקסימים כמו Lucy in the Sky with Diamonds ו־Being for the Benefit of Mr. Kite!. המעבר בין השירים כמעט לא נשבר.",
 "זה נחשב לאחד האלבומים המשפיעים בהיסטוריה, וקבע שאלבום יכול להיות יצירה שלמה. הוא בא אחרי Revolver (אלבום 60), והושפע מ־Pet Sounds (אלבום 61)."],
 [("A Day in the Life","סיום גדול עם תזמורת וצליל אחרון שמתמשך."),("Lucy In The Sky With Diamonds","שיר חלומי עם דימויים צבעוניים."),("With A Little Help From My Friends","רינגו שר שיר שמח ופשוט על חברות.")])

add(79, [
 "Country Joe and the Fish היו להקה מברקלי שבקליפורניה, שהתמקדה בפסיכדליה ובמחאה פוליטית. Electric Music for the Mind and Body יצא ב־1967, שנת ה־Summer of Love.",
 "האלבום מלא בגיטרות חשמליות, באורגן מהדהד ובמילים על אהבה, חופש ומסעות תודעה. Section 43 הוא קטע אינסטרומנטלי ארוך, ו־Flying High פותח את האלבום בקצב חיוני.",
 "זה אחד האלבומים שמראים איך נשמעה ברקלי של אותה תקופה. אם אהבתם את הצליל של אלבום 96, Surrealistic Pillow, כאן תמצאו עוד ממנו."],
 [("Flying High","פתיחה קצבית ומלאת הבטחות."),("Section 43","קטע אינסטרומנטלי ארוך שמזכיר מסע."),("Bass Strings","שיר על חוויה פסיכדלית, בקצב איטי וחלומי.")])

add(80, [
 "Buffalo Springfield היו להקה שבה נפגשו שלושה יוצרים גדולים: סטיבן סטילס, ניל יאנג וריצ'י פיורי. ב־1967 הם הקליטו את האלבום השני שלהם, והמתחים בין החברים כבר השפיעו על העבודה.",
 "כל אחד הוסיף שירים משלו, וכך יצא אלבום מגוון: Mr. Soul של יאנג נפתח בגיטרה חדה, Expecting to Fly מתנשא עם תזמורת, ו־Bluebird של סטילס מתחיל באקוסטית ומסתיים בסולו רועם.",
 "זה אחד האלבומים שבנו גשר בין הפולק, הרוק והקאנטרי. מחברי הלהקה יצאו כמה מהיוצרים הגדולים של שנות ה־70."],
 [("Mr. Soul","פתיחה חשמלית עם ריף חד וטקסט על תהילה."),("Expecting to Fly","שיר עדין עם תזמורת, כמעט חלום."),("Bluebird","שיר של סטילס עם סיום גיטרות חזק.")])

add(74, [
 "The Yardbirds, להקה בריטית שכבר הכירה את קלפטון ואת בק, הוציאה ב־1966 את Roger the Engineer, שנקרא גם Over Under Sideways Down. זה האלבום היחיד שנכתב כולו על ידי חברי הלהקה, ובו ג'ף בק הוא הגיטריסט המוביל.",
 "הגיטרה של בק פורצת כאן החוצה: היא מצחקקת, צורחת, ומפזרת צלילים שנשמעים כמעט כמו מכונות. Lost Women ו־The Nazz Are Blue הם בלוז מהיר ועצבני, ו־Over, Under, Sideways, Down הוא הסינגל שהפך לסימן היכר של התקופה.",
 "הירדבירדס הפכו כאן ללהקה ניסיונית, שהשפיעה על הרוק הקשה והפסיכדלי בשנים שאחר כך. אם אהבתם את Blues Breakers (אלבום 73), כאן תשמעו את הכיוון הבא של הגיטרה הבריטית."],
 [("Over, Under, Sideways, Down","סינגל קצבי עם גיטרה מזרחית מוזרה."),("Lost Women","בלוז מהיר שנפתח כמו מרוץ."),("The Nazz Are Blue","בלוז שבו ג'ף בק גם שר וגם מנגן.")])

add(81, [
 "Moby Grape נוסדה בסן פרנסיסקו ב־1966, והייתה להקה של חמישה זמרים ויוצרים. Columbia הוציאה את אלבום הבכורה שלהם ב־1967 בהמון רעש, ואפילו שחררה כמה סינגלים בבת אחת, מה שהכביד עליהם.",
 "האלבום נשמע כמו כל מה שהיה אפשרי בסן פרנסיסקו: שלוש גיטרות שמתכתבות, הרמוניות, קאנטרי ובלוז, ושירים שהיו יכולים להיות להיטים. Omaha, Hey Grandma ו־Sitting by the Window שווים האזנה.",
 "זה אלבום שהיה צריך להיות ענק ונשאר סוד יפה. אם אהבתם את Surrealistic Pillow (אלבום 96), זה חלק מאותו עולם."],
 [("Omaha","שיר קצבי עם שלוש גיטרות חשמליות."),("Hey Grandma","פתיחה קצבית ומלאת חיים."),("Sitting by the Window","שיר רך ופשוט, עם הרמוניות נעימות.")])

add(82, [
 "Love, להקה מלוס אנג'לס בהובלת ארתור לי, הוציאה ב־1966 את Da Capo, האלבום השני שלה. זה האלבום שבו הלהקה עוברת מגראז' רוק קצבי לצליל עשיר יותר, עם צלילי צ'מבלו וג'אז.",
 "צד אחד של התקליט מלא בשירים קצרים ושונים זה מזה, כמו 7 and 7 Is המהיר והעצבני, ו־She Comes in Colors הרך והמסתורי. הצד השני הוא Revelation, אלתור של כתשע עשרה דקות שממלא אותו כולו.",
 "זה אחד האלבומים הפסיכדליים המגוונים ביותר של התקופה, והוא מוביל אל Forever Changes (אלבום 87), ההישג הגדול של הלהקה."],
 [("7 and 7 Is","שיר עצבני ומהיר, כמעט פאנק לפני הזמן."),("She Comes In Colors","שיר רך וחלומי, עם צ'מבלו."),("Revelation","אלתור ארוך שממלא את הצד השני.")])

add(83, [
 "קפטן ביפהארט (שמו האמיתי דון ואן פליט) הוציא ב־1967 את אלבום הבכורה שלו עם להקתו, Safe as Milk. הוא שר בקול נמוך וחזק, כמו זמר בלוז שמגיע מעולם אחר.",
 "האלבום מחבר בלוז, רוק וצלילים מוזרים: Electricity נשמע כמו חשמל שעולה על בהלה, Zig Zag Wanderer מתפתל ו־Abba Zaba מוכר בזכות כותרת ששייכת לחטיף אמריקאי. הגיטרה של ריי קודר הצעיר מוסיפה שכבה של אמינות.",
 "זו הנקודה שבה הבלוז פוגש את הפסיכדליה, והוא מוביל אל Trout Mask Replica, האלבום המוזר יותר שיבוא. שווה להתחיל כאן."],
 [("Electricity","שיר מוזר ומסעיר, כמו חשמל שחי."),("Zig Zag Wanderer","שיר מתפתל עם קצב בלוז."),("Abba Zaba","שיר מקפץ על חטיף אמריקאי, עם הומור מוזר.")])

add(84, [
 "The Beau Brummels הגיעו מסן פרנסיסקו והצליחו ב־1965 עם שירים כמו Laugh, Laugh. Triangle, שיצא ב־1967, הוא אלבום שקט ואישי יותר, שבו הלהקה כבר לא מנסה להיות להקת להיטים.",
 "הצליל כאן רך ומוזר: גיטרות אקוסטיות, קול סוחף של סאל ולנטינו, וכלים כמו צ'מבלו וכלי מיתר. Are You Happy? פותח בעדינות, Magic Hollow שקט וחולמני, ו־Nine Pound Hammer מציע שיר עבודה ישן בעיבוד חדש.",
 "זה תקליט שנשכח למדי, אבל הוא חלק מהצליל שקדם לקאנטרי־רוק. אם אהבתם את Buffalo Springfield (אלבום 80), כאן תמצאו משהו מאותו מקום."],
 [("Are You Happy?","פתיחה עדינה עם קול מלא רגש."),("Magic Hollow","שיר חולמני עם עיבוד עדין."),("Nine Pound Hammer","שיר עבודה עממי בעיבוד רך.")])

add(85, [
 "The Monkees נוצרו ב־1966 כלהקה לטלוויזיה, ובהתחלה נגני אולפן ניגנו את המוזיקה שלהם. ב־1967 הלהקה התעקשה לנגן בעצמה, ו־Headquarters הוא האלבום הראשון שבו הם עשו זאת.",
 "האלבום נשמע חברי, קליל ופחות מלוטש: שירים כמו Forget That Girl, Shades of Gray ו־Mr. Webster שמראים צד רגוע יותר מהלהיטים המוכרים. מיכאל נסמית' תורם שירים בסגנון קאנטרי, ומיקי דולנץ כותב את Randy Scouse Git.",
 "זה סיפור על להקה שרצתה להיות אמיתית, וקיבלה את זה. הוא נחשב לאחד האלבומים המפתיעים והנחמדים של התקופה."],
 [("Randy Scouse Git","שיר מוזר ושמח של מיקי דולנץ, שכתב על חוויות בלונדון."),("Shades of Gray","בלדה מלנכולית ועדינה."),("For Pete's Sake","שיר קצבי שהפך מוכר משום שהיה בפתיחה של סדרת הטלוויזיה בעונה השנייה.")])

add(86, [
 "טים באקלי היה זמר צעיר מקליפורניה, שהוציא את האלבום השני שלו ב־1967, בגיל עשרים. לימים אחד מבניו, ג'ף באקלי, יהפוך גם הוא למוזיקאי גדול.",
 "Goodbye and Hello מלא באנרגיה ובקול נדיר שנע בין טווחים רחבים. הגיטרה האקוסטית בת שתים עשרה המיתרים מתחברת לכלי מיתר ולצלילים חלומיים, כמו ב־Pleasant Street וב־Morning Glory, ובמילים של לארי בקט.",
 "זה אחד האלבומים היפים והאמיצים של שנת 1967, בין פולק לפסיכדליה, והוא מראה זמר שלא מפחד להשתנות."],
 [("Morning Glory","שיר עדין ומרגש, על אדם שמחפש את מקומו."),("Pleasant Street","פתיחה קצבית עם קול מלא כוח."),("Goodbye and Hello","שיר הכותרת, מרחף ומהורהר.")])

add(87, [
 "Love מלוס אנג'לס, בהובלת ארתור לי, הקליטה ב־1967 את Forever Changes. הלהקה עצמה הייתה במצב לא פשוט, אבל האלבום יצא מלא קסם, כמעט כמו מחשבה על המוות בתוך חלום.",
 "הגיטרות האקוסטיות מתחברות לתזמורת ולחצוצרות בסגנון מקסיקני, כמו ב־Alone Again Or, שהפך לשיר הידוע ביותר שלהם. יש כאן שירים מרהיבים ומוזרים, כמו The Red Telephone ו־You Set the Scene, והמילים מתעסקות באהבה, בפחד ובחלום.",
 "בזמנו האלבום כמעט לא נמכר, אבל עם הזמן נחשב לאחד האלבומים הגדולים של התקופה. הוא ההמשך הטבעי של Da Capo (אלבום 82)."],
 [("Alone Again Or","הפתיחה, עם חצוצרות מקסיקניות וגיטרה אקוסטית."),("The Red Telephone","שיר מחשיך ומוזר על פחד."),("You Set the Scene","סיום ארוך ומרגש, כמעט כמו סיפור.")])

add(88, [
 "Cream, שלישייה בריטית של קלפטון, ג'ק ברוס וג'ינג'ר בייקר, הקליטה ב־1967 את Disraeli Gears בניו יורק, עם הפקה של פליקס פאפלארדי. הלהקה נחשבה לאחד ה־supergroups הראשונים.",
 "האלבום מחבר בלוז, פסיכדליה ורוק חזק. Sunshine of Your Love פותח בריף גיטרה שהפך לאגדה, Strange Brew עוקצני, ו־Tales of Brave Ulysses מלא בגיטרה וואה־וואה חלומית. גם העטיפה הצבעונית מזוהה איתו.",
 "זה אחד האלבומים שהקנו לרוק את הגיטרה הכבדה. אם אהבתם את Blues Breakers (אלבום 73), תשמעו כאן לאן קלפטון המשיך."],
 [("Sunshine of Your Love","הריף המפורסם ביותר בתולדות הרוק."),("Strange Brew","בלוז עוקצני עם קול מרושע."),("Tales of Brave Ulysses","שיר חלומי עם וואה־וואה.")])

add(89, [
 "פינק פלויד הייתה ב־1967 להקה צעירה מלונדון בהובלת סיד בארט. The Piper at the Gates of Dawn הוקלט באולפני אבי רוד, באותו זמן שבו הביטלס עבדו על Sgt. Pepper (אלבום 78).",
 "האלבום מלא בדמיון: שירים על גמדים ועל חלל, כמו The Gnome ו־Astronomy Domine, וקטעים ארוכים כמו Interstellar Overdrive. הצליל מוזר ומרחף, עם גיטרות מהדהדות ואורגן משונה.",
 "זה האלבום היחיד שבו בארט הוא הכוח המוביל של הלהקה. זמן קצר אחר כך עזב, והלהקה המשיכה לדרכים אחרות, אבל כאן נשמע הקסם הראשון."],
 [("Astronomy Domine","פתיחה גדולה עם קול מרחף ומילים על חלל."),("Interstellar Overdrive","אלתור ארוך על גיטרה מהדהדת."),("The Gnome","שיר מתוק וילדותי על גמד, מסוג הסיפורים שבארט אהב.")])

add(90, [
 "The Who הוציאו ב־1967 את The Who Sell Out, אלבום מבוסס על רעיון מצחיק: שידור של תחנת רדיו פיראטית, עם שירים ופרסומות מדומות באמצע. הפרסומות, כמו Heinz Baked Beans ו־Odorono, הן חלק מהמוזיקה.",
 "הלהקה מחליפה בין רוק חזק, פופ מתוק ושירים מוזרים. I Can See for Miles הוא שיר עוצמתי שהפך ללהיט בארצות הברית, ו־Armenia City in the Sky פותח בצלילים הפוכים שמזכירים פסיכדליה. בסוף יש את Rael, מעין אופרת רוק קצרה.",
 "זה אלבום שמראה את המחשבה של פיט טאונשנד לגבי מה אפשר לעשות מעבר לשיר הבודד, והוא קרוב לפני אופרת הרוק הגדולה Tommy."],
 [("I Can See for Miles","שיר עוצמתי ורועם, ההצלחה הגדולה של הלהקה בארצות הברית."),("Armenia City in the Sky","פתיחה מוזרה עם צלילים הפוכים."),("Heinz Baked Beans","פרסומת מדומה שהפכה לשיר.")])

add(91, [
 "The Velvet Underground הייתה להקה מניו יורק שנוסדה על ידי לו ריד וג'ון קייל, ואנדי וורהול הפך למנהלה והעניק את עטיפת הבננה המפורסמת. האלבום יצא ב־1967, עם הזמרת ניקו בכמה שירים.",
 "השירים מדברים על דברים שהרוק לא אהב לדבר עליהם: הרואין ב־Heroin, סדיזם ב־Venus in Furs, וחיים בלילה ב־I'm Waiting for the Man. לצידם יש שירים יפים ועדינים כמו Sunday Morning ו־Femme Fatale, בקולה של ניקו.",
 "האלבום נמכר מעט בזמנו, אבל השפיע כל כך עד שנאמר שכל מי שקנה אותו הקים להקה. אם אהבתם את הצד העדין, שמעו גם את Chelsea Girl של ניקו (אלבום 77)."],
 [("Heroin","שיר ארוך ומהפנט על התמכרות."),("Femme Fatale","שיר עדין בקולה של ניקו."),("I'm Waiting for the Man","שיר קצבי ועוקצני על מציאת סם ברחובות ניו יורק.")])

add(92, [
 "פרנק סינטרה, שהיה ב־1967 בן חמישים ואחת, הקליט אלבום עם המלחין הברזילאי אנטוניו קרלוס ז'ובים, כאשר עומד בפני שניהם שינוי בטעם בפופ. האלבום קצר, עם עשרה שירים בלבד.",
 "סינטרה שר כמעט בלחישה, והגיטרה של ז'ובים מלווה אותו בעדינות. The Girl from Ipanema, Dindi ו־Quiet Nights of Quiet Stars הם שירי בוסה נובה שקטים וגם קצת עצובים. התזמור של קלאוס אוגרמן מצנן את הכול.",
 "זה אלבום של אינטימיות: שניים גדולים שלא ממהרים. אם אהבתם את Getz / Gilberto (אלבום 41), זו דרך נוספת לפגוש את הסגנון, ואם אהבתם את סינטרה (אלבומים 1 ו־7), זו הפעם שבה הוא שר חרש."],
 [("The Girl From Ipanema","הגרסה השקטה והאינטימית של השיר המפורסם."),("Dindi","שיר געגוע עדין."),("Quiet Nights of Quiet Stars","הקולות היחידים כאן הם קול, גיטרה ושקט.")])

add(93, [
 "The Doors היו להקה מלוס אנג'לס בהובלת ג'ים מוריסון, עם ריי מנזרק על האורגן, ובלי בסיסט קבוע בהקלטות. האלבום הראשון שלהם יצא בינואר 1967 והפך אותם ללהקה מפורסמת.",
 "האלבום נפתח ב־Break On Through ומכיל את Light My Fire, עם סולו אורגן ארוך, ואת Alabama Song, שיר של ברכט וקורט וייל. הוא נסגר ב־The End, שיר של אחת עשרה דקות שמוריסון שר בקול בלתי צפוי.",
 "זה אלבום שהראה שאפשר לשלב רוק, ג'אז ותיאטרון. מבחינה מסוימת הוא ההיפך מה־Summer of Love הנעים: אפל, מסתורי ומסוכן."],
 [("Light My Fire","שיר עם סולו אורגן ארוך, ואחד הלהיטים הגדולים של התקופה."),("Break On Through (To The Other Side)","פתיחה קצבית ומהירה."),("The End","סיום דרמטי של אחת עשרה דקות.")])

add(94, [
 "The Byrds ב־1967 כבר היו בלי גן קלארק, ודייויד קרוסבי וכריס הילמן הפכו ליוצרים חשובים יותר. Younger Than Yesterday מציג להקה שמשתנה ומתבוננת בעצמה.",
 "האלבום נפתח ב־So You Want to Be a Rock 'n' Roll Star, שיר עוקצני על תעשיית המוזיקה, כולל חצוצרה של הו מסקלה. יש כאן גם My Back Pages של דילן, ושירים של קרוסבי כמו Everybody's Been Burned, מלאים באווירה חלומית.",
 "זה אלבום שמאחד פולק, רוק וקצת קאנטרי, והוא מראה את הלהקה בשלב חזק. שמעו גם את Mr. Tambourine Man (אלבום 57) ואת Fifth Dimension (אלבום 63) כדי להבין את המסע שלה."],
 [("So You Want to Be a Rock 'n' Roll Star","שיר עוקצני על תעשיית המוזיקה, עם חצוצרה."),("My Back Pages","גרסה מרגשת לשיר של דילן."),("Everybody's Been Burned","שיר עדין ועצוב של דייויד קרוסבי.")])

add(95, [
 "The Young Rascals היו להקה מניו יורק, ומהראשונות ששילבו רוק עם סול, כשהזמרים שלהם לבנים אבל הצליל שחור. Groovin' יצא ב־1967, והשיר הכותרת שלו עלה לראש המצעד האמריקאי.",
 "האלבום מלא באורגן וחם, בקולות מתוקים ובשירים כמו How Can I Be Sure, שהוא בלדה נהדרת, ו־A Girl Like You. הצליל חלק וקליל, ומזכיר יום שבת אחר צהריים.",
 "זה אלבום פופ־סול שהתעלם מהפסיכדליה של התקופה, ובמקום זה שמר על השמחה. הוא מאפשר לשמוע צד אחר של 1967."],
 [("Groovin'","שיר קליל ומרגיע, להיט ענק."),("How Can I Be Sure","בלדה מתוקה ועצובה."),("A Girl Like You","שיר קצבי וקליל.")])

add(96, [
 "Jefferson Airplane מסן פרנסיסקו הקליטה ב־1967 את Surrealistic Pillow, אחרי שגרייס סליק הצטרפה ללהקה. ג'רי גרסיה מהגרייטפול דד קיבל בקרדיט את התואר יועץ רוחני.",
 "סליק הביאה שני שירים גדולים: Somebody to Love, שיר של תשוקה וחופש, ו־White Rabbit, שיר על עליסה בארץ הפלאות עם קצב שמזכיר בולרו. השירים סביבם רכים ופולקיים, כמו Today ו־My Best Friend.",
 "זה אחד האלבומים שהגדירו את הצליל של סן פרנסיסקו ואת הקיץ של 1967. הוא חבר טוב ל־Electric Music for the Mind and Body (אלבום 79)."],
 [("Somebody to Love","שיר חזק ונחוש, שהפך להמנון."),("White Rabbit","שיר מסתורי על עליסה, שמתפרץ בסוף."),("Today","בלדה רכה ומלנכולית.")])

add(97, [
 "ריי דייויס, מנהיג הקינקס, כתב ב־1967 אלבום שהתעלם לגמרי מהאופנות. Something Else by The Kinks יצא בזמן שהפסיכדליה שלטה, והוא עסק במקום זה בחיי היומיום הבריטיים.",
 "השירים מציירים דמויות ותמונות: David Watts על נער פופולרי בבית הספר, Death of a Clown של דייב דייויס על ליצן עצוב, ו־Waterloo Sunset, אחד השירים היפים ביותר על לונדון, שבו אדם מתבונן בעיר מחלון.",
 "האלבום לא נמכר טוב, אבל הוא נחשב היום לאחד הטובים של הלהקה. זה המשך ישיר של Face to Face (אלבום 66)."],
 [("Waterloo Sunset","שיר שקט ויפהפה על לונדון, אחד השירים הגדולים של שנות ה־60."),("David Watts","שיר קצבי על נער פופולרי וקנאה."),("Death of a Clown","שיר של דייב דייויס על ליצן עצוב.")])

add(98, [
 "דונובן, זמר סקוטי צעיר, נחשב בתחילת שנות ה־60 ל'דילן הבריטי'. ב־1966 הוציא את Sunshine Superman, אלבום שבו עבר מפולק פשוט לצלילים מורכבים יותר.",
 "השיר הכותרת עלה לראש המצעד האמריקאי, עם גיטרה ובס בסגנון ג'אזי. Season of the Witch שקט ואפל, ו־Legend of a Girl Child Linda מספר על נערה בסיפור חלומי. האלבום מלא בהומור ועדינות.",
 "זה אחד האלבומים ששילבו פולק וג'אז ופסיכדליה בצורה רכה, והוא מראה איך המוזיקה השתנתה בין 1965 ל־1966."],
 [("Sunshine Superman","שיר חלומי שהפך ללהיט עולמי."),("Season of the Witch","שיר אפל ואיטי, ובעל השפעה רבה."),("Legend of a Girl Child Linda","סיפור מתוק ועדין על ילדה.")])

add(99, [
 "מרל האגרד גדל בבייקרספילד שבקליפורניה, ישב בכלא סן קוונטין כצעיר, ואחר כך הפך לאחד היוצרים הגדולים של הקאנטרי. I'm a Lonesome Fugitive יצא ב־1967, והוא נקרא על שם השיר הפותח.",
 "הצליל כאן הוא הצליל של בייקרספילד: גיטרות חשמליות חדות, קולות חמים, וסיפורים על אנשים פשוטים ועל כישלון. Life in Prison ו־Skid Row משקפים ניסיון אישי, בלי להתנצל.",
 "האלבום נחשב לאחד הראשונים שהראו את האגרד כיוצר ולא רק כזמר. אם אהבתם את Ray Charles בקאנטרי (אלבום 31), זה קאנטרי אחר, גולמי וישיר."],
 [("I'm a Lonesome Fugitive","שיר על בורח מהחוק, עם קצב חזק."),("Life in Prison","שיר על עונש ועל חרטה."),("Skid Row","שיר על הרחוב, באמת ובלי הצגות.")])

add(100, [
 "ג'ימי הנדריקס, גיטריסט מסיאטל, נדד לניו יורק ולבסוף התגלה על ידי צ'אס צ'נדלר, בסיסט לשעבר של The Animals, שהביא אותו ללונדון. ב־1967 הקליטו הנדריקס, נואל רדינג ומיץ' מיצ'ל את Are You Experienced.",
 "הגיטרה של הנדריקס נשמעת כמו משהו שלא נשמע לפני כן: צרחות, פידבק וצלילים מעוותים שמגיעים ישר מלב הבלוז. הוא מנגן את Purple Haze ואת Foxy Lady בעוצמה, ואת The Wind Cries Mary בעדינות. הגרסה האמריקאית, שאותה תשמעו כאן, כוללת שלושה סינגלים.",
 "זה אחד האלבומים החשובים בתולדות הרוק, והוא מסכם את המסע של האלבומים הראשונים: מהבלוז דרך הפולק עד הפסיכדליה. הוא סוגר את מאה האלבומים הראשונים בתחושה של התחלה חדשה."],
 [("Purple Haze","הריף שקבע את הצליל של הרוק הכבד."),("The Wind Cries Mary","בלדה עדינה ויפהפייה."),("Hey Joe","גרסה משלו לשיר מוכר, עם גיטרה שרה.")])

# ---- second round of corrections ----
add(83, [
 "קפטן ביפהארט (שמו האמיתי דון ואן פליט) הוציא ב־1967 את אלבום הבכורה של להקתו, Safe as Milk. הוא שר בקול נמוך וגס, כמו זמר בלוז שמגיע מעולם אחר.",
 "האלבום מחבר בלוז, רוק וצלילים מוזרים: Electricity חשמלי ומטורף, Zig Zag Wanderer מתפתל, ו־Abba Zaba נקרא על שם חטיף אמריקאי. הגיטרה של ריי קודר הצעיר מוסיפה שכבה של בלוז אמיתי.",
 "זו נקודת המפגש של הבלוז והפסיכדליה, והתחלה של דרך מוזרה עוד יותר שקפטן ביפהארט ימשיך בה באלבומים הבאים. שווה להתחיל כאן."],
 [("Electricity","שיר מוזר ומסעיר, כמו חשמל שחי."),("Zig Zag Wanderer","שיר מתפתל עם קצב בלוז."),("Abba Zaba","שיר מקפץ על חטיף אמריקאי, עם הומור מוזר.")])

add(84, [
 "The Beau Brummels הגיעו מסן פרנסיסקו והצליחו ב־1965 עם שירים כמו Laugh, Laugh. Triangle, שיצא ב־1967, הוא אלבום שקט ואישי יותר, שבו הלהקה כבר לא מנסה להיות להקת להיטים.",
 "הצליל כאן רך ומוזר: גיטרות אקוסטיות וקולו הנוגה של סאל ולנטינו. Are You Happy? פותח בעדינות, Magic Hollow שקט וחולמני, ו־Nine Pound Hammer מציע שיר עבודה עממי בעיבוד חדש.",
 "זה תקליט שנשכח למדי, אבל הוא חלק מהצליל שקדם לקאנטרי־רוק. אם אהבתם את Buffalo Springfield (אלבום 80), כאן תמצאו משהו מאותו מקום."],
 [("Are You Happy?","פתיחה עדינה עם קול מלא רגש."),("Magic Hollow","שיר חולמני עם עיבוד עדין."),("Nine Pound Hammer","שיר עבודה עממי בעיבוד רך.")])

add(86, [
 "טים באקלי היה זמר צעיר מקליפורניה, שהוציא את האלבום השני שלו ב־1967, בגיל עשרים. לימים בנו, ג'ף באקלי, יהפוך גם הוא למוזיקאי גדול.",
 "Goodbye and Hello מלא באנרגיה ובקול נדיר שנע בין טווחים רחבים. הגיטרה האקוסטית מתחברת לעיבודים עשירים ולצלילים חלומיים, כמו ב־Pleasant Street וב־Morning Glory, ובמילים שכתב לארי בקט.",
 "זה אחד האלבומים היפים והאמיצים של שנת 1967, בין פולק לפסיכדליה, והוא מראה זמר שלא מפחד להשתנות."],
 [("Morning Glory","שיר עדין ומרגש על נודד בודד."),("Pleasant Street","שיר קצבי ורב־שכבות."),("Goodbye and Hello","שיר הכותרת, מרחף ומהורהר.")])

add(88, [
 "Cream, שלישייה בריטית של אריק קלפטון, ג'ק ברוס וג'ינג'ר בייקר, הקליטה ב־1967 את Disraeli Gears בניו יורק, עם פליקס פאפלארדי כמפיק. הלהקה נחשבה לאחת מלהקות העל הראשונות.",
 "האלבום מחבר בלוז, פסיכדליה ורוק חזק. Sunshine of Your Love נפתח בריף גיטרה שהפך לאגדה, Strange Brew עוקצני, ו־Tales of Brave Ulysses מלא בגיטרה וואה־וואה חלומית. גם העטיפה הצבעונית מזוהה איתו.",
 "זה אחד האלבומים שהקנו לרוק את הגיטרה הכבדה. אם אהבתם את Blues Breakers (אלבום 73), תשמעו כאן לאן קלפטון המשיך."],
 [("Sunshine of Your Love","אחד הריפים המפורסמים ביותר בתולדות הרוק."),("Strange Brew","בלוז עוקצני עם קול מרושע."),("Tales of Brave Ulysses","שיר חלומי עם וואה־וואה.")])

add(92, [
 "פרנק סינטרה, שהיה ב־1967 בן חמישים ואחת, הקליט אלבום עם המלחין הברזילאי אנטוניו קרלוס ז'ובים, כשהבוסה נובה כבר כבשה את העולם. האלבום קצר, עם עשרה שירים בלבד.",
 "סינטרה שר כמעט בלחישה, והגיטרה של ז'ובים מלווה אותו בעדינות. The Girl from Ipanema, Dindi ו־Quiet Nights of Quiet Stars הם שירי בוסה נובה שקטים וקצת עצובים, בעיבוד מעודן של קלאוס אוגרמן.",
 "זה אלבום של אינטימיות: שניים גדולים שלא ממהרים. אם אהבתם את Getz / Gilberto (אלבום 41), זו דרך נוספת לפגוש את הסגנון, ואם אהבתם את סינטרה (אלבומים 1 ו־7), זו הפעם שבה הוא שר חרש."],
 [("The Girl From Ipanema","הגרסה השקטה והאינטימית של השיר המפורסם."),("Dindi","שיר געגוע עדין."),("Quiet Nights of Quiet Stars","שיר לילה שקט ורך.")])

add(99, [
 "מרל האגרד גדל בבייקרספילד שבקליפורניה, ישב בכלא סן קוונטין כצעיר, ואחר כך הפך לאחד היוצרים הגדולים של הקאנטרי. I'm a Lonesome Fugitive יצא ב־1967, והוא נקרא על שם השיר הפותח.",
 "הצליל כאן הוא הצליל של בייקרספילד: גיטרות חשמליות חדות, קולות חמים, וסיפורים על אנשים פשוטים ועל כישלון. Life in Prison ו־Skid Row מדברים על עולם שהוא הכיר מקרוב, בלי להתנצל.",
 "האלבום אחד מאלה שביססו את מעמדו של האגרד. אם אהבתם את ריי צ'ארלס בקאנטרי (אלבום 31), זה קאנטרי אחר, גולמי וישיר."],
 [("I'm a Lonesome Fugitive","שיר על בורח מהחוק, עם קצב חזק."),("Life in Prison","שיר על עונש ועל חרטה."),("Skid Row","שיר על הרחוב, באמת ובלי הצגות.")])

add(85, [
 "The Monkees נוצרו ב־1966 כלהקה לטלוויזיה, ובהתחלה נגני אולפן ניגנו את המוזיקה שלהם. ב־1967 הלהקה התעקשה לנגן בעצמה, ו־Headquarters הוא האלבום הראשון שבו הם עשו זאת.",
 "האלבום נשמע חברי, קליל ופחות מלוטש: שירים כמו Forget That Girl, Shades of Gray ו־Mr. Webster שמראים צד רגוע יותר מהלהיטים המוכרים. מיכאל נסמית' תורם שירים בסגנון קאנטרי, ומיקי דולנץ כותב את Randy Scouse Git.",
 "זה סיפור על להקה שרצתה להיות אמיתית, וקיבלה את זה. הוא נחשב לאחד האלבומים המפתיעים והנחמדים של התקופה."],
 [("Randy Scouse Git","שיר מוזר ושמח של מיקי דולנץ, בהשראת ביקור בלונדון."),("Shades of Gray","בלדה מלנכולית ועדינה."),("For Pete's Sake","שיר קצבי ששימש בסיום סדרת הטלוויזיה של הלהקה.")])

add(82, [
 "Love, להקה מלוס אנג'לס בהובלת ארתור לי, הוציאה ב־1966 את Da Capo, האלבום השני שלה. זה האלבום שבו הלהקה עוברת מגראז' רוק קצבי לצליל עשיר יותר.",
 "צד אחד של התקליט מלא בשירים קצרים ושונים זה מזה, כמו 7 and 7 Is המהיר והעצבני, ו־She Comes in Colors הרך והמסתורי. הצד השני הוא Revelation, אלתור של כתשע עשרה דקות שממלא אותו כולו.",
 "זה אחד האלבומים הפסיכדליים המגוונים ביותר של התקופה, והוא מוביל אל Forever Changes (אלבום 87), ההישג הגדול של הלהקה."],
 [("7 and 7 Is","שיר עצבני ומהיר, כמעט פאנק לפני הזמן."),("She Comes In Colors","שיר רך וחלומי."),("Revelation","אלתור ארוך שממלא את הצד השני.")])
